import pyomo.environ as pyo

DATA = {
    "modes": ["helicopter", "bus"],
    "patients_per_trip": {"helicopter": 5, "bus": 8},
    "hours_per_trip": {"helicopter": 1, "bus": 3},
    "min_patients": 120,
    "min_helicopter_share": 0.30,   # fraction of trips that must be helicopter
    "max_bus_trips": 10,
}


def build_model(data=None):
    d = data or DATA

    model = pyo.ConcreteModel()

    # --- Sets ---
    model.MODES = pyo.Set(initialize=d["modes"])

    # --- Variables ---
    def trips_bounds(m, i):
        if i == "bus":
            return (0, d["max_bus_trips"])
        return (0, None)

    model.trips = pyo.Var(
        model.MODES,
        domain=pyo.NonNegativeIntegers,
        bounds=trips_bounds,
    )

    # --- Objective: minimise total transport time ---
    def obj_rule(m):
        return sum(d["hours_per_trip"][i] * m.trips[i] for i in m.MODES)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    # --- Constraints ---

    # At least min_patients must be transported
    def patient_requirement_rule(m):
        return sum(
            d["patients_per_trip"][i] * m.trips[i] for i in m.MODES
        ) >= d["min_patients"]

    model.patient_requirement = pyo.Constraint(rule=patient_requirement_rule)

    # At least min_helicopter_share of trips must be by helicopter
    # trips[heli] >= s * (trips[heli] + trips[bus])
    # => (1 - s) * trips[heli] - s * trips[bus] >= 0
    def helicopter_share_rule(m):
        s = d["min_helicopter_share"]
        return (1 - s) * m.trips["helicopter"] - s * m.trips["bus"] >= 0

    model.helicopter_share = pyo.Constraint(rule=helicopter_share_rule)

    # At most max_bus_trips bus trips
    def bus_trip_limit_rule(m):
        return m.trips["bus"] <= d["max_bus_trips"]

    model.bus_trip_limit = pyo.Constraint(rule=bus_trip_limit_rule)

    return model


